prompt --application/shared_components/user_interface/templates/list/spotlight_choice
begin
wwv_flow_imp_shared.create_list_template(
 p_id=>wwv_flow_imp.id(810726150913326057)
,p_list_template_before_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-TSpotlightChoice #COMPONENT_CSS_CLASSES#" id="#LIST_ID#" data-item="" data-group-label="Choose an option">',
'<ul class="amc-TSpotlightChoice-list">'))
,p_list_template_after_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'</ul>',
'</div>'))
,p_list_template_current=>'<li class="amc-TSpotlightChoice-item is-current amc-TSpotlightChoice-item--#A02#" data-value="#A04#"><a class="amc-TSpotlightChoice-card" href="#LINK#" aria-current="page"><span class="amc-TSpotlightChoice-flag">Recommended</span><span class="amc-TSpotlightChoice-top"><span class="amc-TSpotlightChoice-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TSpotlightChoice-name">#TEXT#</span><span class="amc-TSpotlightChoice-radio" aria-hidden="true"></span></span><span class="amc-TSpotlightChoice-price">#A03#</span><span class="amc-TSpotlightChoice-desc">#A01#</span></a></li>'
,p_list_template_noncurrent=>'<li class="amc-TSpotlightChoice-item amc-TSpotlightChoice-item--#A02#" data-value="#A04#"><a class="amc-TSpotlightChoice-card" href="#LINK#"><span class="amc-TSpotlightChoice-flag">Recommended</span><span class="amc-TSpotlightChoice-top"><span class="amc-TSpotlightChoice-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TSpotlightChoice-name">#TEXT#</span><span class="amc-TSpotlightChoice-radio" aria-hidden="true"></span></span><span class="amc-TSpotlightChoice-price">#A03#</span><span class="amc-TSpotlightChoice-desc">#A01#</span></a></li>'
,p_list_template_name=>'AMC Spotlight Choice'
,p_internal_name=>'AMC_TPL_SPOTLIGHT_CHOICE'
,p_javascript_file_urls=>'#APP_FILES#amc-templates/amc-tpl-spotlight-choice.js'
,p_theme_id=>42
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-spotlight-choice.css'
,p_a01_label=>'Description'
,p_a02_label=>'Recommended'
,p_a03_label=>'Price or value'
,p_a04_label=>'Return value'
,p_list_template_comment=>'List template for a List region of options. Principles applied: von Restorff, the isolation effect: the entry with Attribute 2 = recommended is the only solid, raised card with a Recommended flag in words, so it is not recognised by colour alone, while every other card stays quiet and identical; if several entries say recommended, only the first one is highlighted. Serial position: the script places the recommended entry first, where primacy makes it noticed and remembered; with Centre stage it goes in the middle of the row, the natural comparison anchor, and its isolation keeps it out of the serial-position valley. Attributes: Attribute 1 is the description, Attribute 2 is recommended or empty, Attribute 3 is the price or value, such as SAR 1,200 per month or Delivered tomorrow, Attribute 4 is the value written to the page item, the label when empty. The icon is the entry image. Selection: name the page item that receives the choice either in the region''s Custom Attributes as data-amc-choice-item="P20_PLAN" or in data-item on the wrapper in Before List Entry. The list then becomes a radio group: the card that matches the item''s current value is selected on load, a click, Space or Enter selects a card and writes its value with apex.item().setValue, which fires the item''s change event for dynamic actions, and the arrow keys move and select as native radios do, Home and End go to the first and last, and Tab enters and leaves the group on the selected card, else the recommended one. Without a page item the cards are plain links to each entry''s target. Template options: Centre stage puts the recommended entry in the middle. Stacked rows shows one option per row with the price at the end, for long descriptions and narrow columns. Quiet highlight isolates the recommended card with a tinted fill and a strong outline instead of a solid fill, for pages that already have a strong primary button. Preselect recommended selects the recommended entry and writes its value when the item is empty. Without JavaScript the cards are links in the order of the list and the recommended card is still highlighted. English UI strings to translate in the template: Recommended, in each entry, and data-group-label, the radio group''s name when the region has no heading. Reduced motion removes the hover transitions.'
);
end;
/
