,p_name=>'MIDDLE'
,p_display_name=>'Centre stage'
,p_display_sequence=>10
,p_list_template_id=>wwv_flow_imp.id(810726150913326057)
,p_css_classes=>'amc-TSpotlightChoice--middle'
,p_template_types=>'LIST'
,p_help_text=>'Places the recommended entry in the middle of the options, where it anchors the comparison, instead of first. Best for three options in a row.'
);
end;
